export const organizacion = {
  raiz: { scps: ["FullAWSAccess"] },
  unidades: [
    {
      nombre: "Produccion",
      cuentas: ["222222222222", "333333333333"],
      scps: ["FullAWSAccess", "DenegarFueraDeRegionesAprobadas"],
    },
  ],
  scps: {
    FullAWSAccess: { efecto: "Allow", acciones: ["*"] },
    DenegarFueraDeRegionesAprobadas: { efecto: "Deny", acciones: ["*"], condicion: "region fuera de la lista aprobada" },
  },
};

spec.code:
const defs: Record<string, { efecto: string }> = organizacion.scps;
const niveles = [organizacion.raiz, ...organizacion.unidades];
for (const nivel of niveles) {
  assert.ok(nivel.scps.some((id: string) => defs[id].efecto === "Allow"), "falta una SCP que permita acciones en un nivel");
}

const produccion = organizacion.unidades.find((u) => u.nombre === "Produccion");
assert.ok(produccion !== undefined, "la UO Produccion debe existir");
assert.ok(produccion.scps.includes("DenegarFueraDeRegionesAprobadas"), "se debe conservar la SCP de denegación");

